div.script:
                        function loadLessonPrograms(page = 1) {
                            fetch(`/teacher_dashboard/lesson-programs?page=${page}`)
                                .then(response => response.text())
                                .then(html => {
                                    document.getElementById('lesson-programs-content').innerHTML = html;

                                    document.querySelectorAll('#lesson-programs-content .page-link').forEach(link => {
                                        link.addEventListener('click', function (event) {
                                            event.preventDefault();
                                            const newPage = parseInt(new URL(this.href).searchParams.get('page'));
                                            loadLessonPrograms(newPage);
                                        });
                                    });
                                })
                                .catch(error => console.error('Error loading lesson programs:', error));
                        }

                        function loadUpcomingLessons(page = 1) {
                            fetch(`/teacher_dashboard/upcoming-lessons?page=${page}`)
                                .then(response => response.text())
                                .then(html => {
                                    document.getElementById('upcoming-lessons-content').innerHTML = html;

                                    // Attach event listeners to dynamically loaded pagination links
                                    document.querySelectorAll('#upcoming-lessons-content .page-link').forEach(link => {
                                        link.addEventListener('click', function (event) {
                                            event.preventDefault();
                                            const newPage = parseInt(new URL(this.href).searchParams.get('page'));
                                            loadUpcomingLessons(newPage);
                                        });
                                    });
                                })
                                .catch(error => console.error('Error loading upcoming lessons:', error));
                        }
                        
                        function loadCompletedLessons(page = 1) {
                            fetch(`/teacher_dashboard/completed-lessons?page=${page}`)
                                .then(response => response.text())
                                .then(html => {
                                    document.getElementById('completed-lessons-content').innerHTML = html;

                                    // Add event listeners for pagination links
                                    document.querySelectorAll('#completed-lessons-content .page-link').forEach(link => {
                                        link.addEventListener('click', function (event) {
                                            event.preventDefault();
                                            const newPage = parseInt(new URL(this.href).searchParams.get('page'));
                                            loadCompletedLessons(newPage);
                                        });
                                    });

                                    // Add event listeners for "View Students" buttons
                                    document.querySelectorAll('.toggle-students').forEach(button => {
                                        button.addEventListener('click', function () {
                                            const studentList = document.getElementById('student-list-' + this.getAttribute('data-id'));
                                            studentList.classList.toggle('d-none');
                                        });
                                    });
                                })
                                .catch(error => console.error('Error loading completed lessons:', error));
                        }
                        
                        function loadMasterClasses(page = 1) {
                            fetch(`/teacher_dashboard/master-classes?page=${page}`)
                                .then(response => response.text())
                                .then(html => {
                                    document.getElementById('master-classes-content').innerHTML = html;

                                    // Add event listeners for pagination links
                                    document.querySelectorAll('#master-classes-content .page-link').forEach(link => {
                                        link.addEventListener('click', function (event) {
                                            event.preventDefault();
                                            const newPage = parseInt(new URL(this.href).searchParams.get('page'));
                                            loadMasterClasses(newPage);
                                        });
                                    });
                                })
                                .catch(error => console.error('Error loading master classes:', error));
                        }

                        
                        function markLessonCompleted(button) {
                                const lessonId = button.getAttribute('data-id');

                                fetch('/teacher_dashboard/mark_lesson_completed', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { lesson_id: lessonId }, id: new Date().getTime() })
                                })
                                .then(response => response.json())
                                .then(data => {
                                    if (data.success) {
                                        
                                        loadUpcomingLessons(); // Reload the list after completion
                                        loadCompletedLessons(); // Move the lesson to completed list
                                    } else {
                                        alert('Error: ' + data.message);
                                    }
                                })
                                .catch(error => {
                                    console.error('Error:', error);
                                    alert('An unexpected error occurred.');
                                });
                            }

                            function markMasterclassCompleted(button) {
                                const masterclassId = button.getAttribute('data-id');

                                fetch('/teacher_dashboard/mark_masterclass_completed', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { masterclass_id: masterclassId }, id: new Date().getTime() })
                                })
                                .then(response => response.json())
                                .then(data => {
                                    if (data.success) {
                                        
                                        loadMasterClasses(); // Reload the list after completion
                                        loadCompletedLessons(); // Move the masterclass to completed list
                                    } else {
                                        alert('Error: ' + data.message);
                                    }
                                })
                                .catch(error => {
                                    console.error('Error:', error);
                                    alert('An unexpected error occurred.');
                                });
                            }


                         document.addEventListener("DOMContentLoaded", function () {
                            
                            loadUpcomingLessons();
                            loadLessonPrograms();
                            loadCompletedLessons();
                            loadMasterClasses();
                        });
